from decimal import Decimal, ROUND_HALF_UP
from typing import Any


def _value(row: dict, key: str) -> Any:
    value = row.get(key, "")
    return "" if value is None else value


def _fixed(value: Any, width: int) -> str:
    text = str(value)
    return text[:width].ljust(width)


def _zpad(value: Any, width: int) -> str:
    cents = (Decimal(str(value)) * Decimal("100")).quantize(
        Decimal("1"),
        rounding=ROUND_HALF_UP,
    )
    return str(int(cents)).zfill(width)


def format_account(row: dict) -> str:
    """Return the 77-character legacy EXPORT_ACCT fixed-width record."""
    annual_revenue = _value(row, "ANN_REV")
    if annual_revenue == "":
        annual_revenue = 0

    credit_hold = _value(row, "CRED_HOLD")
    if credit_hold == "":
        credit_hold = "N"

    create_date = _value(row, "CREATE_DT")
    if create_date == "":
        create_date = "00000000"

    return (
        _fixed(_value(row, "ACCT_ID"), 10)
        + _fixed(_value(row, "ACCT_NM"), 40)
        + _fixed(_value(row, "REGION_CD"), 3)
        + _zpad(annual_revenue, 15)
        + str(credit_hold)
        + str(create_date)
    )
